            opspagev.showField("exampleOficense");
        } else if (fieldValue == "4") {
            opspagev.hideField("certificatesPhoto");
            opspagev.hideField("personalSupplierBackPicture");
            opspagev.hideField("passportPhoto");
            opspagev.hideField("passPhoto");//港澳通行证
            opspagev.showField("twpassPhoto");//台湾通行证
            opspagev.showField("exampleOficense");
        } else {
            opspagev.showField("certificatesPhoto");
            opspagev.showField("personalSupplierBackPicture");
            opspagev.hideField("passportPhoto");
            opspagev.hideField("passPhoto");//港澳通行证
            opspagev.hideField("twpassPhoto");//台湾通行证
            opspagev.hideField("exampleOficense");
        }
    }
    if (fieldCode == "countrySelection") {
        if (fieldValue == "1") {
            opspagev.hideField("address");
            opspagev.showField("detailAddress");

        } else {
            opspagev.hideField("detailAddress");
            opspagev.showField("address");
        }
    }
    if (fieldCode == "businessLicenseEndDate") {
        if (opspagev.formData.businessLicenseBeginDate > opspagev.formData.businessLicenseEndDate) {
            OPSMessage("error", "开始时间不能大于截止时间");
        }
    }
    if (fieldCode == "disabledTime") {
        if (opspagev.formData.establishDate > opspagev.formData.disabledTime) {
            OPSMessage("error", "成立日期不能大于证件有效期");
        }
    }
    //判断供应商名称是否存在
    if (fieldCode == "supplierName") {
        //   /supplier/update/supplierName?supplierName=xxx&supplierId=xxx
        if (opspagev.formData.supplierType != "1"){
            var resultSupplierName = OPSExecInterface("{center-test}/supplier/update/supplierName", { "supplierName": opspagev.formData.supplierName, "supplierId": opspagev.formData.supplierId }, "GET");
            // OPSMessage("error", resultSupplierName);
            if (resultSupplierName.Code == "Fail") {
                OPSMessage("error", resultSupplierName.Message);
                opspagev.formData.supplierName = "";
            }
        }
    }
    if (fieldCode == "certificatesCode") {
        if (opspagev.formData.licenseType == "1"){
            var regex = /^[\\d]{6}(19|20)\\d{2}(0[1-9]|1[0-2])(0[1-9]|[12]\\d|3[01])[\\d]{3}([\\dXx])$/;
            var result = validateRegex(fieldValue, regex);
            if (result == false){
                OPSMessage("error", "请输入正确的证件号码！");
                return;
            }
        }
        if (opspagev.formData.licenseType == "2"){
            var regex = /^[HM]\\d{8}([A-Za-z0-9]){1,4}$/;
            var result = validateRegex(fieldValue, regex);
            if (result == false){
                OPSMessage("error", "请输入正确的港澳通行证！");
                return;
            }
        }
        if (opspagev.formData.licenseType == "3"){
            var regex = /^[A-Za-z0-9]{6,18}$/;;
            var result = validateRegex(fieldValue, regex);
            if (result == false){
                OPSMessage("error", "请输入正确的护照！");
                return;
            }
        }

        var resultBlackSupplier = OPSExecInterface("{center-test}/supplier/supplierBlackVerification", { "unifiedSocialCertificateCode": opspagev.formData.certificatesCode }, "GET");
        if (resultBlackSupplier.Message == "供应商已拉黑！") {
            OPSMessage("error", resultBlackSupplier.Message);
        } else {
            var resultUnifiedSocialCertificateCode = OPSExecInterface("{center-test}/supplier/update/socialCreditCode", { "socialCreditCode": opspagev.formData.certificatesCode, "supplierId": opspagev.formData.supplierId }, "GET");
            console.log("统一社会信用代码:" + JSON.stringify(resultUnifiedSocialCertificateCode))
            if (resultUnifiedSocialCertificateCode.Code == "Fail") {
                OPSMessage("error", resultUnifiedSocialCertificateCode.Message);
            }
        }
    }
    if (fieldCode == "unifiedSocialCertificateCode") {
        var resultBlackSupplier = OPSExecInterface("{center-test}/supplier/supplierBlackVerification", { "unifiedSocialCertificateCode": opspagev.formData.unifiedSocialCertificateCode }, "GET");
        if (resultBlackSupplier.Message == "供应商已拉黑！") {
            OPSMessage("error", "供应商已拉黑！");
        } else {
            // /supplier/update/socialCreditCode?socialCreditCode=xxx&supplierId=xxx
            var resultUnifiedSocialCertificateCode = OPSExecInterface("{center-test}/supplier/update/socialCreditCode", { "socialCreditCode": opspagev.formData.unifiedSocialCertificateCode, "supplierId": opspagev.formData.supplierId }, "GET");
            console.log("统一社会信用代码:" + JSON.stringify(resultUnifiedSocialCertificateCode))
            if (resultUnifiedSocialCertificateCode.Code == "Fail") {
                OPSMessage("error", resultUnifiedSocialCertificateCode.Message);
            }
        }
    }
    if (fieldCode == "abroadCertificatesCode") {
        var resultBlackSupplier = OPSExecInterface("{center-test}/supplier/supplierBlackVerification", { "unifiedSocialCertificateCode": opspagev.formData.abroadCertificatesCode }, "GET");
        if (resultBlackSupplier.Message == "供应商已拉黑！") {
            OPSMessage("error", "供应商已拉黑！");
        } else {
            var resultUnifiedSocialCertificateCode = OPSExecInterface("{center-test}/supplier/update/socialCreditCode", { "socialCreditCode": opspagev.formData.abroadCertificatesCode, "supplierId": opspagev.formData.supplierId }, "GET");
            console.log("统一社会信用代码:" + JSON.stringify(resultUnifiedSocialCertificateCode))
            if (resultUnifiedSocialCertificateCode.Code == "Fail") {
                OPSMessage("error", resultUnifiedSocialCertificateCode.Message);
            }
        }
    }

    if (fieldCode == "countrySelection") {
        if (fieldValue == "0") {
            opspagev.formData.detailAddress = "";
        }
        if (fieldValue == "1") {
            opspagev.formData.address = {}
        }
    }

    // 待审批和已审批页面
    if (OPSProcessInfo){
        opspagev.hideField("exampleOficense");
        opspagev.setFieldReadOnly("business", true);
        opspagev.setFieldReadOnly("abroadCertificate", true);
        opspagev.setFieldReadOnly("certificatesPhoto", true);
        opspagev.setFieldReadOnly("personalSupplierBackPicture", true);
        opspagev.setFieldReadOnly("passPhoto", true);
        opspagev.setFieldReadOnly("twpassPhoto", true);
        opspagev.setFieldReadOnly("passportPhoto", true);
        opspagev.hideField("updateButton");
        // 2是只读，1是显示按钮
        opspagev.formData.statusStr = "2";
    }
}

