            opspagev.setFieldVisible("field274",true);
            opspagev.setFieldVisible("field275",false);
        } else if(statusStr =="2" && approvalIdType == false && approvalType == false && (top.OPSThirdPartyTokenInfo==null || top.OPSThirdPartyTokenInfo == "")){
            //2=预览页面并且不是已审批进来和待审批进来,并且不是在协同门户页面
            opspagev.setFieldVisible("field274",false);
            opspagev.setFieldVisible("field275",true);
        }else if (statusStr =="1" && approvalIdType == false && approvalType == false && top.OPSThirdPartyTokenInfo!=null) {
            //1=修改页面并且不是已审批进来和待审批进来,并且是在协同门户页面
            opspagev.setFieldVisible("field274",true);
            opspagev.setFieldVisible("field275",false);
        }else if (statusStr =="2" && approvalIdType == false && approvalType == false && top.OPSThirdPartyTokenInfo!=null) {
            //2=预览页面并且不是已审批进来和待审批进来,并且是在协同门户页面
            opspagev.setFieldVisible("field274",false);
            opspagev.setFieldVisible("field275",true);
        }else{
            opspagev.setFieldVisible("field274",false);
            opspagev.setFieldVisible("field275",false);
        }
    }catch(e){
        opspagev.setFieldVisible("field274",false);
        opspagev.setFieldVisible("field275",false);
    }

    //如果页面是已审批，或者待审批或者页面是预览页面都是只读
