        readOnlyZx();
        opspagev.setFieldVisible("field274",false);
        opspagev.setFieldVisible("field275",false);
    }

}


//加载页面变更历史数据
function changeHistoryLoading(supplierId, approvalId, approvalIdType, approvalType, statusStr){
    //如果页面是已审批，或者待审批或者页面是预览页面都是只读
    if(approvalIdType ==true || approvalType ==true || statusStr!="1"){
        debugger
        var param={
            "idList":supplierId,
            "approvalId":approvalId
        };
        var result = OPSExecInterface("{center-test}/supplier/update/supplierBasicInfoChangeDetailList", param, "GET");
        if (result.Code != "Fail" && result.Content !=null && result.Content !="") {
            var data = JSON.parse(result.Content);
            // 遍历整个 data 数组
            var addressValue = "";
            data.forEach(function(item) {
                convertNumbersToString(item);
                if (item['fieldCode'] == "address"){
                    addressValue = item['beforeValue'];
                }
            });

            data.forEach(function(item) {
                if (addressValue !== ""){
                    if (item['fieldCode'] == "detailAddress"){
                        item['beforeValue'] = addressValue;
                    }
                }
            });

            console.log("jsonContent:"+JSON.stringify(data));

            // 使用map函数来转换data数组
            let changeResult = data.map(item => ({
                key: item.fieldCode,
                beforeValue: item.beforeValue
            }));
            //赋值变更历史数据
            opspagev.formDataComparison(JSON.stringify(changeResult))
        }
    }
}


